-- 模板商店的多 catalog 源管理（对齐 cf-manager 的 catalog_sources 表）
CREATE TABLE IF NOT EXISTS catalog_sources (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  url TEXT NOT NULL,
  name TEXT NOT NULL,
  is_default INTEGER NOT NULL DEFAULT 0,
  enabled INTEGER NOT NULL DEFAULT 1,
  last_synced TEXT,
  last_status TEXT NOT NULL DEFAULT 'unknown',
  last_error TEXT,
  etag TEXT,
  cached_catalog TEXT,
  cached_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);

-- 装机（instrepos）网络源管理：对齐 catalog_sources 的多源缓存模式
CREATE TABLE IF NOT EXISTS instrepos_sources (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  url TEXT NOT NULL,
  name TEXT NOT NULL,
  is_default INTEGER NOT NULL DEFAULT 0,
  enabled INTEGER NOT NULL DEFAULT 1,
  last_synced TEXT,
  last_status TEXT NOT NULL DEFAULT 'unknown',
  last_error TEXT,
  etag TEXT,
  cached_catalog TEXT,
  cached_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
-- ============================================================
-- 种子数据：默认源（内置目录 / 内置装机源）
-- 幂等：WHERE NOT EXISTS 避免重复执行时重复插入。
-- ============================================================
INSERT INTO catalog_sources (url, name, is_default, enabled, last_status, cached_catalog, cached_at, created_at)
SELECT 'builtin://cfstore', '默认目录', 1, 1, 'ok', '{"version":"1.0.0","name":"模板商店","description":"内置模板：直接挑选并部署到任意已接入的 Cloudflare 账户。","templates":[{"id":"hello-worker","name":"Hello Worker","description":"最小的 Cloudflare Worker：返回问候语、部署时间和可选的环境变量问候。","version":"1.0.0","type":"worker","tags":["worker","hello","入门"],"author":{"name":"Supportly"},"script":"export default {\n  async fetch(request, env, ctx) {\n    const greeting = env.GREETING || \"Hello\";\n    const now = new Date().toISOString();\n    return new Response(`${greeting}, from Cloudflare at ${now}\\n`, {\n      headers: { \"Content-Type\": \"text/plain; charset=utf-8\", \"Access-Control-Allow-Origin\": \"*\" }\n    });\n  }\n};","compatibilityDate":"2024-11-01","vars":[{"name":"GREETING","label":"问候语","type":"plain_text","defaultValue":"你好"}]}]}', datetime('now'), datetime('now')
WHERE NOT EXISTS (SELECT 1 FROM catalog_sources WHERE url = 'builtin://cfstore');

